<template><div class="team-logo" :class="size"><img v-if="src && !failed" :src="src" :alt="name" @error="failed=true"/><span v-else>{{initials}}</span></div></template>
<script setup lang="ts">import {computed,ref,watch} from 'vue';const props=withDefaults(defineProps<{src?:string|null,name?:string,size?:'sm'|'md'|'lg'}>(),{name:'Team',size:'md'});const failed=ref(false);watch(()=>props.src,()=>failed.value=false);const initials=computed(()=>props.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase());</script>
<style scoped>.team-logo{display:grid;place-items:center;border-radius:50%;background:#f0f3f8;overflow:hidden;flex:none;border:1px solid var(--line);font-weight:800;color:var(--muted)}.team-logo img{width:100%;height:100%;object-fit:contain}.sm{width:32px;height:32px;font-size:9px}.md{width:46px;height:46px;font-size:11px}.lg{width:70px;height:70px;font-size:15px}</style>
